import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) {
        new Main().run();
    }

    void run() {
        InputReader in = new InputReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        int mod = 998244353;
        int n = in.nextInt();
        int k = in.nextInt();
        int[] v = new int[10];
        for (int i = 0; i < k; i++) {
            v[in.nextInt()] = 1;
        }

        int[] ans = {1};
        int p = n / 2;
        while (true) {
            if ((p & 1) == 1) {
                ans = multiply(ans, v, mod);
            }
            v = multiply(v, v, mod);
            p >>= 1;
            if (p == 0) break;
        }

        long res = 0;
        for (int x : ans) {
            res = (res + (long)x * x) % mod;
        }
        out.println(res);
        out.close();
    }

    int[] multiply(int[] a, int[] b, int mod) {
        int need = a.length + b.length - 1;
        int n = Math.max(2, Integer.highestOneBit(need - 1) << 1);

        double[] ar = new double[n];
        double[] ai = new double[n];
        for (int i = 0; i < a.length; i++) {
            long x = (a[i] % mod + mod) % mod;
            ar[i] = x & ((1 << 15) - 1);
            ai[i] = x >> 15;
        }
        fft(ar, ai, false);

        double[] br = new double[n];
        double[] bi = new double[n];
        for (int i = 0; i < b.length; i++) {
            long x = (b[i] % mod + mod) % mod;
            br[i] = x & ((1 << 15) - 1);
            bi[i] = x >> 15;
        }
        fft(br, bi, false);

        double[] fr = new double[n];
        double[] fi = new double[n];
        double[] gr = new double[n];
        double[] gi = new double[n];

        for (int i = 0; i < n; i++) {
            int j = (n - i) & (n - 1);

            double ar1 = (ar[i] + ar[j]) * 0.5;
            double ai1 = (ai[i] - ai[j]) * 0.5;
            double ar2 = (ai[i] + ai[j]) * 0.5;
            double ai2 = (ar[j] - ar[i]) * 0.5;

            double br1 = (br[i] + br[j]) * 0.5;
            double bi1 = (bi[i] - bi[j]) * 0.5;
            double br2 = (bi[i] + bi[j]) * 0.5;
            double bi2 = (br[j] - br[i]) * 0.5;

            fr[i] = ar1 * br1 - ai1 * bi1 - ar2 * bi2 - ai2 * br2;
            fi[i] = ar1 * bi1 + ai1 * br1 + ar2 * br2 - ai2 * bi2;
            gr[i] = ar1 * br2 - ai1 * bi2 + ar2 * br1 - ai2 * bi1;
            gi[i] = ar1 * bi2 + ai1 * br2 + ar2 * bi1 + ai2 * br1;
        }

        fft(fr, fi, true);
        fft(gr, gi, true);

        int[] res = new int[need];
        for (int i = 0; i < need; i++) {
            long a_val = Math.round(fr[i]);
            long b_val = Math.round(gr[i]);
            long c_val = Math.round(fi[i]);
            res[i] = (int)((a_val + ((b_val % mod) << 15) + ((c_val % mod) << 30)) % mod);
        }
        return res;
    }

    void fft(double[] re, double[] im, boolean inverse) {
        int n = re.length;
        for (int i = 1, j = 0; i < n; i++) {
            int bit = n >> 1;
            for (; (j ^= bit) < bit; bit >>= 1);
            if (i < j) {
                double t = re[i]; re[i] = re[j]; re[j] = t;
                t = im[i]; im[i] = im[j]; im[j] = t;
            }
        }

        for (int len = 2; len <= n; len <<= 1) {
            double ang = 2 * Math.PI / len * (inverse ? -1 : 1);
            double wlen_re = Math.cos(ang);
            double wlen_im = Math.sin(ang);

            for (int i = 0; i < n; i += len) {
                double w_re = 1;
                double w_im = 0;
                for (int j = 0; j < len / 2; j++) {
                    double u_re = re[i + j];
                    double u_im = im[i + j];
                    double v_re = re[i + j + len/2] * w_re - im[i + j + len/2] * w_im;
                    double v_im = re[i + j + len/2] * w_im + im[i + j + len/2] * w_re;

                    re[i + j] = u_re + v_re;
                    im[i + j] = u_im + v_im;
                    re[i + j + len/2] = u_re - v_re;
                    im[i + j + len/2] = u_im - v_im;

                    double tmp = w_re * wlen_re - w_im * wlen_im;
                    w_im = w_re * wlen_im + w_im * wlen_re;
                    w_re = tmp;
                }
            }
        }

        if (inverse) {
            for (int i = 0; i < n; i++) {
                re[i] /= n;
                im[i] /= n;
            }
        }
    }

    static class InputReader {
        private final InputStream is;
        private final byte[] buf = new byte[1024];
        private int pos, size;

        public InputReader(InputStream is) {
            this.is = is;
        }

        public int nextInt() {
            int c = read();
            while (c <= 32) c = read();
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            int res = 0;
            do {
                if (c < '0' || c > '9') throw new RuntimeException();
                res = res * 10 + c - '0';
                c = read();
            } while (c > 32);
            return res * sign;
        }

        private int read() {
            if (pos >= size) {
                try {
                    size = is.read(buf);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
                pos = 0;
                if (size <= 0) return -1;
            }
            return buf[pos++] & 255;
        }
    }
}
